    , 
    var `maxIdleConnections`: kotlin.ULong
    , 
    var `connectionIdleTimeoutSeconds`: kotlin.ULong
    , 
    var `retryMaxAttempts`: kotlin.ULong
    , 
    var `retryInitialDelayMillis`: kotlin.ULong
    , 
    var `retryMaxDelayMillis`: kotlin.ULong
    , 
